function toggleSet(e,s){let row=state.active.exercises[e].logs[s];if(!row.done){let w=String(row.weight).replace(',','.'),r=String(row.reps);if(!/^\d+(?:\.\d+)?$/.test(w)||!/^\d+$/.test(r)||+w>2000||+r<1||+r>1000){toast('הזן משקל תקין (0 למשקל גוף) ו־1–1000 חזרות.');return}row.weight=String(+w);row.reps=String(+r)}row.done=!row.done;save();renderActive();if(row.done)startRest(state.active.exercises[e].type==='מורכב'?90:60)}
function updateProgress(){if(!state.active)return;let sets=[...(state.active.archived||[]),...state.active.exercises].flatMap(e=>e.logs),done=sets.filter(x=>x.done).length;$('#workoutProgress').style.width=`${sets.length?done/sets.length*100:0}%`}
function startElapsed(){clearInterval(elapsedTimer);elapsedTimer=setInterval(()=>{if(!state.startedAt)return;let sec=Math.floor((Date.now()-state.startedAt)/1000);$('#elapsedTime').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`},1000)}
function startRest(seconds){rest={endAt:Date.now()+seconds*1000,remaining:null,total:seconds,minimized:true};persistRest();drawTimer()}
function drawTimer(){if(!rest.endAt&&rest.remaining==null){$('#timerDock').hidden=true;return}let left=rest.remaining==null?Math.max(0,Math.ceil((rest.endAt-Date.now())/1000)):rest.remaining;if(left<=0){rest={};persistRest();$('#timerDock').hidden=true;toast('המנוחה הסתיימה');return}$('#timerDock').hidden=false;$('#timerDock').classList.toggle('minimized',!!rest.minimized);$('#timerValue').textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;$('#timerArc').style.strokeDashoffset=119.4*(1-Math.min(1,left/rest.total));$('#timerDismiss').textContent=rest.minimized?'⌃':'⌄';$('#timerDismiss').setAttribute('aria-label',rest.minimized?'הרחב טיימר':'מזער טיימר');$('#timerPause').textContent=rest.remaining==null?'השהה':'המשך'}
function finishWorkout(){if(!state.active||!confirm('לסיים ולשמור את האימון? סטים שלא סומנו לא ייספרו.'))return;let exercises=structuredClone([...(state.active.archived||[]),...state.active.exercises]),duration=Math.max(1,Math.round((Date.now()-state.startedAt)/60000)),done=exercises.flatMap(e=>e.logs).filter(x=>x.done),volume=done.reduce((n,s)=>n+(+s.weight||0)*(+s.reps||0),0),entry={id:crypto.randomUUID(),date:new Date().toISOString(),title:state.active.title,duration,volume,sets:done.length,exercises};let previousActive=state.active,previousStart=state.startedAt;let completedDay=state.week?.[state.active.day],previousCompletion=completedDay?.completedAt;if(completedDay)completedDay.completedAt=entry.date;state.history.unshift(entry);state.active=null;state.startedAt=null;if(!save()){if(completedDay){if(previousCompletion)completedDay.completedAt=previousCompletion;else delete completedDay.completedAt}state.history.shift();state.active=previousActive;state.startedAt=previousStart;return}rest={};persistRest();drawTimer();clearInterval(elapsedTimer);$('#finishDuration').textContent=duration;$('#finishVolume').textContent=Math.round(volume).toLocaleString('he-IL');$('#finishSets').textContent=done.length;let text=encodeURIComponent(`אימון כוח|${duration}|${Math.round(duration*6.5)}`);$('#healthShortcut').href=`shortcuts://run-shortcut?name=Log%20Workout&input=text&text=${text}`;showModal('finishModal');confetti();renderActive();renderStats();renderWeek()}
function renderLibrary(filter='all',term=''){$('#catalogCount').textContent=EXERCISES.length+' תרגילים';let muscles=['all',...Object.keys(MUSCLE_HE)];$('#muscleFilters').innerHTML=muscles.map(m=>`<button class="chip ${m===filter?'active':''}" data-muscle="${m}">${m==='all'?'הכול':MUSCLE_HE[m]}</button>`).join('');let list=EXERCISES.filter(e=>(filter==='all'||e.muscle===filter)&&(`${esc(e.he)} ${e.en} ${e.equipment}`.toLowerCase().includes(term.toLowerCase())));$('#exerciseGrid').innerHTML=list.map(e=>`<button class="exercise-card" data-exercise="${e.id}"><div class="exercise-visual" style="${visualStyle(e)}"></div><div class="info"><h3>${esc(e.he)}</h3><p>${e.en}</p><div class="tags"><span class="tag">${e.type}</span><span class="tag">${e.equipment}</span></div></div></button>`).join('');$$('[data-muscle]').forEach(b=>b.onclick=()=>renderLibrary(b.dataset.muscle,$('#exerciseSearch').value));$$('[data-exercise]').forEach(b=>b.onclick=()=>openExercise(+b.dataset.exercise))}
function openExercise(id){let e=EXERCISES.find(x=>x.id===id),v=$('#modalVisual');v.style.cssText=visualStyle(e);v.setAttribute('role','img');v.setAttribute('aria-label',`איור ${e.he}: התחלה וסיום`);$('#modalMeta').textContent=`${MUSCLE_HE[e.muscle]} · ${e.type} · ${e.equipment}`;$('#modalName').textContent=e.he;$('#modalEnglish').textContent=e.en;$('#modalCue').innerHTML=exerciseGuidance(e);showModal('exerciseModal')}
function calcStreak(){let weekStart=t=>{let d=new Date(t);d.setHours(0,0,0,0);d.setDate(d.getDate()-d.getDay());return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`},weeks=new Set(state.history.map(h=>weekStart(h.date)));let d=new Date(),count=0;if(!weeks.has(weekStart(d)))d.setDate(d.getDate()-7);while(weeks.has(weekStart(d))){count++;d.setDate(d.getDate()-7)}return count}
function deleteWorkout(index){
  if(!Number.isInteger(index)||index<0||index>=state.history.length)return;
  const workout=state.history[index];
  if(!confirm(`למחוק את האימון "${workout.title}" מתאריך ${new Date(workout.date).toLocaleDateString('he-IL')}? האימון וכל הסטים שלו יוסרו מההיסטוריה ומהסטטיסטיקות. לא ניתן לבטל. מומלץ לייצא גיבוי לפני המחיקה.`))return;
  const previous=state.history;
  state.history=previous.filter((_,i)=>i!==index);
  if(!save()){state.history=previous;return}
  renderStats();renderActive();toast('האימון נמחק והסטטיסטיקות עודכנו');
}
function renderStats(){let total=state.history.reduce((n,h)=>n+h.volume,0),streak=calcStreak();$('#streakValue').textContent=streak;$('#statsStreak').textContent=streak;$('#totalWorkouts').textContent=state.history.length;$('#totalVolume').textContent=total>999?`${(total/1000).toFixed(1)}k`:Math.round(total);$('#historyList').innerHTML=state.history.length?state.history.map((h,index)=>`<article class="history-item"><div class="history-icon">✓</div><div class="history-info"><b>${esc(h.title)}</b><small>${new Date(h.date).toLocaleDateString('he-IL')} · ${h.duration} דקות</small></div><div class="history-volume"><b>${Math.round(h.volume).toLocaleString('he-IL')}</b><small>ק״ג נפח</small></div><button type="button" class="delete-workout" data-delete-workout="${index}" aria-label="מחיקת אימון ${esc(h.title)} מתאריך ${new Date(h.date).toLocaleDateString('he-IL')}">מחק</button></article>`).join(''):`<div class="empty-state" style="padding:30px"><p>האימון הראשון שלך יופיע כאן.</p></div>`;$$('[data-delete-workout]').forEach(button=>button.onclick=()=>deleteWorkout(Number(button.dataset.deleteWorkout)));drawChart()}
function drawChart(){let c=$('#volumeChart'),ctx=c.getContext('2d'),dpr=devicePixelRatio||1,w=c.clientWidth,h=180;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);let vals=[0,0,0,0],now=new Date;state.history.forEach(x=>{let diff=Math.floor((now-new Date(x.date))/6048e5);if(diff<4)vals[3-diff]+=x.volume});let max=Math.max(...vals,100),pad=26;let colors=getComputedStyle(document.documentElement),accent=colors.getPropertyValue('--accent').trim(),success=colors.getPropertyValue('--success').trim();ctx.strokeStyle=colors.getPropertyValue('--line').trim();ctx.lineWidth=1;for(let i=0;i<4;i++){let y=pad+i*(h-2*pad)/3;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}let pts=vals.map((v,i)=>[i*(w-24)/3+12,h-pad-(v/max)*(h-2*pad)]);let grad=ctx.createLinearGradient(0,0,w,0);grad.addColorStop(0,accent);grad.addColorStop(1,success);ctx.strokeStyle=grad;ctx.lineWidth=3;ctx.lineJoin='round';ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();ctx.lineTo(pts[3][0],h-pad);ctx.lineTo(pts[0][0],h-pad);ctx.closePath();let fill=ctx.createLinearGradient(0,pad,0,h);fill.addColorStop(0,success+'30');fill.addColorStop(1,success+'00');ctx.fillStyle=fill;ctx.fill();pts.forEach(p=>{ctx.beginPath();ctx.arc(...p,4,0,Math.PI*2);ctx.fillStyle=success;ctx.fill()})}
function confetti(){let c=$('#confettiCanvas'),ctx=c.getContext('2d');c.width=innerWidth;c.height=innerHeight;let bits=Array.from({length:90},()=>({x:Math.random()*c.width,y:-20-Math.random()*c.height/2,v:2+Math.random()*5,r:Math.random()*6+3,a:Math.random()*6.2,c:['#b7ff3c','#43e6db','#ff8a3d','#fff'][Math.floor(Math.random()*4)]}));let n=0;(function frame(){ctx.clearRect(0,0,c.width,c.height);bits.forEach(b=>{b.y+=b.v;b.x+=Math.sin(b.y/30);b.a+=.07;ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.a);ctx.fillStyle=b.c;ctx.fillRect(-b.r,-b.r/2,b.r*2,b.r);ctx.restore()});if(n++<180)requestAnimationFrame(frame)})()}
function go(name){$$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===name));$$('.nav-item').forEach(b=>{let active=b.dataset.target===name;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(name==='stats')renderStats();scrollTo({top:0,behavior:'smooth'})}
function showModal(id){let m=$('#'+id);m.classList.add('show');m.setAttribute('aria-hidden','false')}
function hideModal(id){let m=$('#'+id);m.classList.remove('show');m.setAttribute('aria-hidden','true')}
let toastTimer;function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function init(){let d=new Date;$('#todayLabel').textContent=d.toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long'});renderWeek();renderActive();renderLibrary();renderStats();if(state.active)startElapsed();$$('.nav-item').forEach(b=>b.onclick=()=>go(b.dataset.target));$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('#generateBtn').onclick=generateWeek;$('#rerollAll').onclick=generateWeek;$('#finishWorkout').onclick=finishWorkout;$('#timerSkip').onclick=()=>{rest={};persistRest();drawTimer()};$('#timerDismiss').onclick=()=>{rest.minimized=!rest.minimized;persistRest();drawTimer()};$('#searchToggle').onclick=()=>$('#searchWrap').classList.toggle('show');$('#exerciseSearch').oninput=e=>{let current=$('.chip.active')?.dataset.muscle||'all';renderLibrary(current,e.target.value)};$$('[data-close]').forEach(b=>b.onclick=()=>hideModal(b.dataset.close));$('#finishClose').onclick=()=>{hideModal('finishModal');go('stats')};$$('.modal').forEach(m=>m.onclick=e=>{if(e.target===m&&m.id!=='finishModal')hideModal(m.id)});addEventListener('resize',()=>{if($('#statsView').classList.contains('active'))drawChart()});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js')}
init();

// PulseFit 2: additive migration, detailed logs and deadline-based rest timer.
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function navigateExercise(delta){let a=state.active;if(!a)return;a.cursor=Math.max(0,Math.min(a.exercises.length-1,(a.cursor||0)+delta));save();renderActive()}
function persistRest(){state.rest=rest;save()}
let replacementContext=null;
function openReplacement(target,day,index){replacementContext={target,day,index};let original=target==='active'?state.active.exercises[index]:state.week[day].exercises[index];$('#replaceSearch').value='';$('#replaceMuscle').innerHTML='<option value="all">כל השרירים</option>'+Object.entries(MUSCLE_HE).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');$('#replaceMuscle').value=original.muscle;$('#replaceEquipment').innerHTML='<option value="all">כל הציוד</option>'+[...new Set(EXERCISES.map(e=>e.equipment))].map(v=>`<option>${esc(v)}</option>`).join('');$('#replacePermanent').checked=false;$('#permanentLabel').hidden=target!=='active';renderReplacements();showModal('replaceModal');$('#replaceSearch').focus()}
function renderReplacements(){let q=$('#replaceSearch').value.trim().toLowerCase(),muscle=$('#replaceMuscle').value,equipment=$('#replaceEquipment').value;let list=EXERCISES.filter(e=>(muscle==='all'||e.muscle===muscle)&&(equipment==='all'||e.equipment===equipment)&&`${esc(e.he)} ${e.en}`.toLowerCase().includes(q));$('#replaceResults').innerHTML=list.map(e=>`<article class="replacement"><div class="exercise-visual" style="${visualStyle(e)}"></div><b>${esc(e.he)}</b><small>${esc(e.equipment)} · ${MUSCLE_HE[e.muscle]}</small><details><summary>תצוגה מקדימה</summary>${exerciseGuidance(e)}</details><button class="primary-btn" data-replace-id="${e.id}">בחר תרגיל</button></article>`).join('')||'<p>אין תרגילים תואמים</p>';$$('[data-replace-id]').forEach(b=>b.onclick=()=>applyReplacement(+b.dataset.replaceId))}
function applyReplacement(id){if(!replacementContext)return;let {target,day,index}=replacementContext,chosen=EXERCISES.find(e=>e.id===id);if(!chosen)return;let template={...chosen,...rx(chosen)};if(target==='active'){if(!state.active)return;let old=state.active.exercises[index];if(old.id===id){hideModal('replaceModal');return}let completed=old.logs.filter(s=>s.done);if(completed.length){state.active.archived||=[];state.active.archived.push({...structuredClone(old),logs:structuredClone(completed)})}state.active.exercises[index]={...template,logs:Array.from({length:template.sets},()=>({weight:'',reps:'',done:false}))};if($('#replacePermanent').checked&&state.week?.[day]?.exercises[index])state.week[day].exercises[index]=structuredClone(template);renderActive()}else state.week[day].exercises[index]=template;save();renderWeek();hideModal('replaceModal');toast('התרגיל הוחלף. סטים שבוצעו נשמרו תחת המקור.')}
function exportBackup(){let data={format:'pulsefit-backup',version:2,exportedAt:new Date().toISOString(),state};let url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`pulsefit-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function validateState(s){
  let obj=x=>x&&typeof x==='object'&&!Array.isArray(x), num=x=>typeof x==='number'&&Number.isFinite(x)&&x>=0, text=x=>typeof x==='string'&&x.length<2000;
  if(!obj(s)||!Array.isArray(s.history)||s.history.length>50000)throw Error('פורמט גיבוי לא תקין');
  let exercise=(e,logs=false)=>{if(e?.id===46&&e.cue==null){e.cue=EXERCISES[45].cue;e.equipment=EXERCISES[45].equipment}if(!obj(e)||!EXERCISES.some(x=>x.id===e.id)||!text(e.he)||!text(e.en)||!text(e.cue)||!Object.hasOwn(MUSCLE_HE,e.muscle)||!text(e.type)||!text(e.equipment)||!Number.isInteger(e.sets)||e.sets<1||e.sets>100||!(text(e.reps)||num(e.reps)))throw Error('נתוני תרגיל לא תקינים');if(logs){if(!Array.isArray(e.logs)||e.logs.length>100)throw Error('סטים לא תקינים');for(let r of e.logs)if(!obj(r)||typeof r.done!=='boolean'||![r.weight,r.reps].every(v=>(typeof v==='string'&&v.length<30)||num(v)))throw Error('ערכי סט לא תקינים')}};
  for(let h of s.history){if(!obj(h)||!text(h.title)||!Number.isFinite(Date.parse(h.date))||!num(h.duration)||!num(h.volume)||!num(h.sets))throw Error('היסטוריה לא תקינה');if(h.exercises){if(!Array.isArray(h.exercises)||h.exercises.length>1000)throw Error('היסטוריה מפורטת לא תקינה');h.exercises.forEach(e=>exercise(e,true))}}
  if(s.week!=null){if(!Array.isArray(s.week)||s.week.length>30)throw Error('תוכנית לא תקינה');s.week.forEach(d=>{if(!obj(d)||!text(d.title)||!Array.isArray(d.exercises)||d.exercises.length>100)throw Error('יום אימון לא תקין');if(d.completedAt!=null&&(!text(d.completedAt)||!Number.isFinite(Date.parse(d.completedAt))))throw Error('סימון אימון לא תקין');d.exercises.forEach(e=>exercise(e))})}
  if(s.active!=null){let a=s.active;if(!obj(a)||!text(a.title)||!Number.isInteger(a.day)||a.day<0||!num(s.startedAt)||!Array.isArray(a.exercises)||!a.exercises.length||a.exercises.length>100)throw Error('אימון פעיל לא תקין');a.exercises.forEach(e=>exercise(e,true));if(a.archived){if(!Array.isArray(a.archived)||a.archived.length>1000)throw Error('ארכיון לא תקין');a.archived.forEach(e=>exercise(e,true))}if(a.cursor!=null&&(!Number.isInteger(a.cursor)||a.cursor<0||a.cursor>=a.exercises.length))throw Error('מיקום תרגיל לא תקין')}
  if(s.rest&&Object.keys(s.rest).length){let r=s.rest;if(!num(r.total)||r.total===0||!(num(r.endAt)||num(r.remaining))||!(r.remaining==null||num(r.remaining)))throw Error('טיימר לא תקין')}
  return s;
}
async function importBackup(file){try{if(!file||file.size>20000000)throw Error('בחר קובץ גיבוי עד 20MB');let data=JSON.parse(await file.text());if(data.format!=='pulsefit-backup'||data.version!==2)throw Error('זה אינו גיבוי PulseFit 2');let incoming=validateState(data.state);if(!confirm('השחזור יחליף את הנתונים המקומיים. הורד גיבוי נוכחי לפני ההמשך. להמשיך?'))return;let serialized=JSON.stringify(incoming);localStorage.setItem('pulsefit-before-import',JSON.stringify(state));localStorage.setItem(STORE_KEY,serialized);location.reload()}catch(err){toast(err.message||'השחזור נכשל')}}
function renderDetailedStats(){let selected=$('#statsExercise').value||String(EXERCISES[0].id),id=+selected;let rows=state.history.filter(h=>h.exercises?.some(e=>e.id===id)).slice().reverse().map(h=>{let logs=h.exercises.filter(e=>e.id===id).flatMap(e=>e.logs).filter(s=>s.done);return{date:h.date,max:Math.max(0,...logs.map(s=>+s.weight||0)),volume:logs.reduce((n,s)=>n+(+s.weight||0)*(+s.reps||0),0)}});$('#exerciseProgress').innerHTML=rows.length?`<p>שיא משקל מתועד: <b>${Math.max(...rows.map(r=>r.max))} ק״ג</b></p><table><caption>התקדמות לפי תרגיל, עד 20 האימונים האחרונים</caption><thead><tr><th>תאריך</th><th>משקל מרבי</th><th>נפח ק״ג</th></tr></thead><tbody>${rows.slice(-20).reverse().map(r=>`<tr><td>${new Date(r.date).toLocaleDateString('he-IL')}</td><td>${r.max}</td><td>${Math.round(r.volume)}</td></tr>`).join('')}</tbody></table>`:'<p>אין עדיין סטים מפורטים לתרגיל הזה. סיכומים ישנים נשמרו, אך אי אפשר לשחזר מהם סטים.</p>';let counts={};state.history.filter(h=>Date.now()-Date.parse(h.date)<28*86400000).forEach(h=>(h.exercises||[]).forEach(e=>counts[e.muscle]=(counts[e.muscle]||0)+e.logs.filter(s=>s.done).length));$('#muscleSummary').textContent='סטים מתועדים ב־28 ימים: '+(Object.entries(counts).map(([k,n])=>`${MUSCLE_HE[k]}: ${n}`).join(' · ')||'אין עדיין נתונים');$('#workoutDetails').innerHTML=state.history.slice(0,20).map(h=>`<details><summary>${esc(h.title)} · ${new Date(h.date).toLocaleDateString('he-IL')}</summary>${h.exercises?h.exercises.map(e=>`<p><b>${esc(e.he)}</b>: ${e.logs.filter(s=>s.done).map(s=>`${esc(s.weight||0)} ק״ג × ${esc(s.reps)}`).join(' · ')||'ללא סטים שבוצעו'}</p>`).join(''):'<p>סיכום ישן, ללא פירוט סטים.</p>'}</details>`).join('')}
const legacyRenderStats=renderStats;
renderStats=function(){legacyRenderStats();if($('#statsExercise'))renderDetailedStats()};
function initUpgrade(){
  $('#timerDock').insertAdjacentHTML('beforeend','<div class="timer-controls"><button class="ghost-btn" id="timerPause">השהה</button><button class="ghost-btn" id="timerAdd">+30 שניות</button></div>');
  $('#timerPause').onclick=()=>{if(rest.remaining==null){rest.remaining=Math.max(1,Math.ceil((rest.endAt-Date.now())/1000));rest.endAt=null}else{rest.endAt=Date.now()+rest.remaining*1000;rest.remaining=null}persistRest();drawTimer()};
  $('#timerAdd').onclick=()=>{if(rest.remaining!=null)rest.remaining+=30;else rest.endAt+=30000;rest.total+=30;persistRest();drawTimer()};
  $('#replaceSearch').oninput=renderReplacements;$('#replaceMuscle').onchange=renderReplacements;$('#replaceEquipment').onchange=renderReplacements;$('#replaceClose').onclick=()=>hideModal('replaceModal');
  $('#exportBackup').onclick=exportBackup;$('#importBackup').onchange=e=>{importBackup(e.target.files[0]);e.target.value=''};
  $('#statsExercise').innerHTML=EXERCISES.map(e=>`<option value="${e.id}">${esc(e.he)}</option>`).join('');$('#statsExercise').onchange=renderDetailedStats;
  rest=state.rest||{};clearInterval(timer);timer=setInterval(drawTimer,250);document.addEventListener('visibilitychange',drawTimer);window.addEventListener('pageshow',drawTimer);
  document.addEventListener('keydown',e=>{if(e.key==='Escape')$$('.modal.show:not(#finishModal)').forEach(m=>hideModal(m.id))});
  renderActive();renderStats();drawTimer();if(state.active)go('workout');
}
initUpgrade();

if(window.pulsefitLoadError){let warning=document.createElement('p');warning.className='load-warning';warning.textContent='הנתונים המקוריים לא נטענו. השמירה חסומה. אל תנקה נתוני אתר. כפתור חילוץ יוריד את הנתונים המקוריים לבדיקה.';let b=document.createElement('button');b.textContent='חלץ נתונים מקוריים';b.onclick=()=>{let u=URL.createObjectURL(new Blob([localStorage.getItem(STORE_KEY)||''],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download='pulsefit-recovery.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)};warning.append(b);document.body.prepend(warning)}

$('#addLegDay').onclick=addLegDay;

// Keep canvas colors in sync with the system appearance without reloading a workout.
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if($('#statsView').classList.contains('active'))drawChart()});
